<template><Modal :value="visible" :title="rule?'佣金规则草稿':'合作协议草稿'" width="1050" :mask-closable="false" :closable="!disabled" footer-hide @on-visible-change="changed"><div class="s1-ui"><Alert v-if="previous" show-icon>创建续约新版本；原生效版本正文和历史不覆盖。</Alert><Form :model="form" :label-width="145" class="ui-form"><DetailSection title="关联主体" :grid="false"><FormItem label="商户" required><BusinessSelect v-model="header.storeId" type="stores" :disabled="disabled||!!record||!!previous" @selected="storeSelected"/></FormItem><FormItem v-if="rule" label="关联协议" required><BusinessSelect v-model="header.agreementId" type="agreements" :params="{targetStore:header.storeId||undefined}" :disabled="disabled||!header.storeId||!!record" @selected="agreementSelected"/><p v-if="agreement" class="ui-note">{{agreement.payload.name}} · v{{agreement.revision}} · {{status(agreement.status)}} · {{agreement.payload.startDate}} 至 {{agreement.payload.endDate}}</p></FormItem></DetailSection><DetailSection :title="rule?'规则条款':'协议正文'" :grid="false"><div class="ui-form-grid"><FormItem label="名称" required class="wide"><Input v-model="form.name" :maxlength="rule?60:100" :disabled="disabled"/></FormItem><template v-if="!rule"><FormItem label="平台主体" required><Input v-model="form.platformLegalName" maxlength="100" :disabled="disabled"/></FormItem><FormItem label="商户主体" required><Input v-model="form.merchantLegalName" maxlength="100" :disabled="disabled"/></FormItem><FormItem label="统一社会信用代码" required><Input v-model="form.merchantLegalCode" maxlength="18" :disabled="disabled"/></FormItem><FormItem label="合作类目范围" required><CheckboxGroup v-model="form.categoryIds"><Checkbox v-for="item in categories" :key="item.id" :label="item.id" :disabled="disabled">{{item.path||item.name}}</Checkbox></CheckboxGroup><p v-if="!categories.length" class="ui-note">请先选择商户并读取其批准范围。</p></FormItem></template><FormItem label="开始日期（上海）" required><DatePicker type="date" format="yyyy-MM-dd" :value="form.startDate||''" :disabled="disabled" @on-change="form.startDate=$event"/></FormItem><FormItem label="截止日期（含当日）" required><DatePicker type="date" format="yyyy-MM-dd" :value="form.endDate||''" :disabled="disabled" @on-change="form.endDate=$event"/></FormItem><FormItem label="佣金比例" required><PercentInput :key="formKey" v-model="form.rateBps" :disabled="disabled"/><p class="ui-note">0%是明确免佣，未填写不等于0%。</p></FormItem><FormItem label="计费与取整口径"><p>商品实付不含运费；向下取整到分。</p></FormItem><FormItem label="佣金条款" required class="wide"><Input v-model="form.commissionClause" type="textarea" :rows="4" maxlength="2000" :disabled="disabled"/></FormItem><template v-if="rule"><FormItem label="未来执行依据" class="wide"><p>订单完成且无阻断性售后／退款。本阶段资金执行关闭。</p></FormItem><FormItem label="自动执行商业意向"><Checkbox v-model="form.executionIntent" :disabled="disabled">仅记录意向，当前不执行资金</Checkbox></FormItem><FormItem label="版本备注" class="wide"><Input v-model="form.note" type="textarea" maxlength="500" :disabled="disabled"/></FormItem></template><template v-else><FormItem label="退款规则摘要" required class="wide"><Input v-model="form.refundSummary" type="textarea" :rows="3" maxlength="2000" :disabled="disabled"/></FormItem><FormItem label="双方确认凭据" required class="wide"><Input v-model="form.confirmationReference" maxlength="255" :disabled="disabled"/><p class="ui-note">上传和只读展示不代表电子签署。</p></FormItem></template></div></DetailSection><AttachmentList v-if="!rule" :key="formKey+':'+header.storeId" v-model="form.fileIds" purpose="AGREEMENT" :scope="(record?record.id:previous?previous.id:'new')+':'+header.storeId" title="协议附件" editable multiple :disabled="disabled"/></Form><p v-if="localError||error" class="ui-error">{{localError||error}}</p><footer class="ui-form-footer"><Button :disabled="busy" @click="$emit('cancel')">取消</Button><Button type="primary" :loading="busy" :disabled="disabled" @click="save">保存草稿</Button></footer></div></Modal></template>
<script>import accessible from '../accessibility';import {s1Read} from '@/api/stage1';import {uiRead} from '@/api/stage1-usability';import {status} from '../display.cjs';import BusinessSelect from './BusinessSelect';import PercentInput from './PercentInput';import DetailSection from './DetailSection';import AttachmentList from './AttachmentList';export default {mixins:[accessible],components:{BusinessSelect,PercentInput,DetailSection,AttachmentList},props:{visible:Boolean,record:Object,previous:Object,rule:Boolean,storeId:String,busy:Boolean,disabled:Boolean,error:String},data:()=>({header:{storeId:'',agreementId:''},form:{},categories:[],agreement:null,selectedStoreId:null,ticket:0,formKey:0,localError:''}),watch:{visible(value){if(value)this.initialize();},form:{deep:true,handler(){if(this.visible)this.$emit('dirty');}}},beforeDestroy(){this.ticket++;},methods:{status,initialize(){const row=this.record||this.previous;this.formKey++;this.localError='';this.agreement=null;this.header={storeId:row?row.storeId:this.storeId||'',agreementId:row?row.agreementId:''};this.form=row?JSON.parse(JSON.stringify(row.payload)):{name:'',rateBps:null,startDate:'',endDate:'',baseCode:'PRODUCT_PAID_EXCLUDING_SHIPPING',roundCode:'FLOOR_CENT',...(this.rule?{triggerBasis:'ORDER_COMPLETED_NO_BLOCKING_AFTERSALE',executionIntent:false,note:''}:{platformLegalName:'',merchantLegalName:'',merchantLegalCode:'',categoryIds:[],fileIds:[],confirmationReference:'',commissionClause:'',refundSummary:''})};this.selectedStoreId=this.header.storeId;this.categories=[];if(this.header.storeId)this.loadStore(false);},changed(value){if(!value&&this.visible)this.$emit('cancel');},storeSelected(row){const id=row&&row.id||'';if(id===this.selectedStoreId)return;this.selectedStoreId=id;this.categories=[];if(!this.record&&!this.previous){this.header.agreementId='';this.agreement=null;if(!this.rule){this.form.categoryIds=[];this.form.merchantLegalName='';this.form.merchantLegalCode='';}}if(row)this.loadStore(!this.record&&!this.previous);},async loadStore(fill){const ticket=++this.ticket,id=this.header.storeId;this.localError='';try{const profile=await uiRead('/stores/'+id);if(ticket!==this.ticket||id!==this.header.storeId)return;this.categories=profile.categoryNames||[];if(fill&&!this.rule){this.form.merchantLegalName=profile.legalName;this.form.merchantLegalCode=profile.legalCode;this.form.categoryIds=[...profile.categoryIds];}}catch(e){if(ticket===this.ticket)this.localError=e.message;}},async agreementSelected(option){const id=option&&option.id;if(!id){this.agreement=null;return;}try{const a=await s1Read('/agreements/'+id);if(this.header.agreementId!==id)return;this.agreement=a;if(!this.record&&!this.previous){this.form.rateBps=a.payload.rateBps;this.$set(this.form,'commissionClause',a.payload.commissionClause);this.form.startDate=a.payload.startDate;this.form.endDate=a.payload.endDate;this.formKey++;}}catch(e){if(this.header.agreementId===id)this.localError=e.message;}},save(){this.localError='';if(!this.header.storeId){this.localError='请选择商户。';return;}if(this.rule&&!this.header.agreementId){this.localError='请选择关联协议。';return;}if(this.form.startDate&&this.form.endDate&&this.form.startDate>this.form.endDate){this.localError='开始日期不能晚于截止日期。';return;}this.$emit('save',{header:{...this.header},payload:{...this.form},record:this.record,previous:this.previous});}}};</script>
